#[cfg(test)]
mod tests {
    use super::*;
    use crate::difftest::fakes::{self, machine_rt, FAKE};
    use crate::difftest::{check, elf_image, fresh, run_generated, DATA, GAME_GP};
    use crate::game::bx::bxstringctor::tests::slot_2;
    use crate::game::scripter::ssxscriptengine::tests::{clear, gp_at};

    pub(crate) const OC995_THIS: u32 = DATA + 0x1000;
    pub(crate) const OC995_ITEM: u32 = DATA + 0x2000;
    pub(crate) const OC995_MC: u32 = DATA + 0x3000;
    pub(crate) const OC995_MC_VT: u32 = DATA + 0x4000;
    pub(crate) const OC995_CARD: u32 = DATA + 0x5000;
    pub(crate) const OC995_CARD_VT: u32 = DATA + 0x6000;
    pub(crate) const OC995_KB: u32 = DATA + 0x7000;
    pub(crate) const OC995_SCREEN: u32 = DATA + 0x8000;
    pub(crate) const OC995_SCREEN_B: u32 = DATA + 0x8100;
    pub(crate) const OC995_SCREEN_C: u32 = DATA + 0x8200;
    pub(crate) const OC995_WORLD: u32 = DATA + 0x9000;
    /// Gate word of the oc995 file-load fake (in the machine's own RAM).
    pub(crate) const OC995_CTRL: u32 = DATA + 0x20_0000;
    pub(crate) const OC995_MAGIC: u32 = 0x0995_c0de;
    static OC995_PREV_3DE670: std::sync::atomic::AtomicUsize =
        std::sync::atomic::AtomicUsize::new(0);

    /// `EAFile_AllocRequest` entry (0x3de670) spins on test data: stop the
    /// file-load chain there, only for machines that set the gate word.
    fn oc995_fake_3de670(c: &mut Cpu) {
        if c.bus.read32(OC995_CTRL) != OC995_MAGIC {
            return fakes::fall_back(c, &OC995_PREV_3DE670, ee::s14::f_003de670__generated);
        }
        fakes::fake_call(c, 0x003d_e670);
    }

    /// Real function returning 0 (a vtable slot that reports "no").
    pub(crate) const OC995_ZERO_FN: u32 = 0x0014_06c0;

    /// `OVScreenProfileSavePDA_OnWidgetAction(this, item, event)`: the profile
    /// save screen's widget events (keyboard end, next, previous, option).
    /// The seed picks the event (4..=15, so both out-of-range edges), the
    /// screen's state words, whether a keyboard popup exists and whether the
    /// memory-card vtable slots answer yes or no.
    fn oc995_widget_setup(c: &mut Cpu, seed: u32) {
        let mut r = machine_rt(c, seed, 0x2_11bc8, 4);
        elf_image(c);
        fakes::hook(
            std::ptr::addr_of_mut!(ee::s14::OVERRIDE_003DE670),
            oc995_fake_3de670,
            &OC995_PREV_3DE670,
        );
        c.bus.write32(OC995_CTRL, OC995_MAGIC);
        let ev = 4 + seed % 12;
        let sel = seed / 12;
        let states = [0u32, 1, 2, 3, 4, 6, 5];
        let state = states[(sel % 7) as usize];
        let bits = r.next_u32();
        let busy = bits & 1;
        let has_kb = (bits >> 1) & 1;
        let yes = (bits >> 2) & 1;
        // MC manager singleton, world and the objects hanging off them.
        clear(c, OC995_MC, 0x200);
        c.bus.write32(gp_at(-0x47c), OC995_MC);
        c.bus.write32(gp_at(-0x848), OC995_WORLD);
        clear(c, OC995_WORLD, 0x40);
        c.bus.write32(OC995_MC + 0x748, OC995_MC_VT);
        c.bus.write32(OC995_MC + 0x434, OC995_CARD);
        c.bus.write32(OC995_CARD, OC995_CARD_VT);
        slot_2(c, OC995_MC_VT, 8, 0);
        slot_2(c, OC995_CARD_VT, 0x1b0, 1);
        slot_2(c, OC995_CARD_VT, 0x218, 2);
        if yes == 0 {
            c.bus.write32(OC995_CARD_VT + 0x1b4, OC995_ZERO_FN);
        }
        // The screen and the item.
        clear(c, OC995_THIS, 0x100);
        clear(c, OC995_ITEM, 0x20);
        c.bus.write32(OC995_ITEM + 0x18, r.next_u32() & 0xff);
        c.bus.write32(OC995_THIS + 0x1c0, state);
        c.bus.write32(OC995_THIS + 0x1a8, busy);
        c.bus.write32(OC995_THIS + 0x1cc, r.next_u32() % 4);
        c.bus.write32(
            OC995_THIS + 0x214,
            if seed % 5 == 0 { r.next_u32() } else { 3 },
        );
        c.bus
            .write32(OC995_THIS + 0x1a4, if has_kb == 1 { OC995_KB } else { 0 });
        clear(c, OC995_KB, 0x80);
        c.bus.write32(OC995_THIS + 0x40, OC995_SCREEN);
        c.bus.write32(OC995_SCREEN + 0xd0, OC995_SCREEN_B);
        c.bus.write32(OC995_SCREEN_B + 0x10, OC995_SCREEN_C);
        c.g[A0][0] = sx(OC995_THIS);
        c.g[A1][0] = if seed % 7 == 0 { 0 } else { sx(OC995_ITEM) };
        c.g[A2][0] = ev as u64;
        c.pc = 0x0021_1bc8;
    }

    /// `__sti__all_in_one_fe_cpp(a0, a1)`: the front end's static initialiser.
    /// With `a1 == 0xffff` and `a0 != 0` it builds the overlay constant tables
    /// (float vectors, hashes, records); otherwise it returns at once.
    fn oc995_sti_setup(c: &mut Cpu, seed: u32) {
        let mut r = machine_rt(c, seed, 0x2_127e8, 0);
        elf_image(c);
        let (a0, a1) = match seed % 4 {
            0 => (0, 0xffff),
            1 => (1, 0x1234),
            _ => (1 + r.next_u32() % 5, 0xffff),
        };
        c.g[A0][0] = sx(a0);
        c.g[A1][0] = a1 as u64;
        c.pc = 0x0021_27e8;
    }

    #[test]
    fn c_ov_state_overlay_static_init_destroy_matches() {
        check(
            ee::s05::f_002127e8__generated,
            c_ov_state_overlay_static_init_destroy,
            8,
            &oc995_sti_setup,
        );
    }

    #[test]
    fn c_ov_state_overlay_static_init_destroy_covers_paths() {
        let mut costs = std::collections::BTreeSet::new();
        for seed in 0..8 {
            let mut c = fresh();
            oc995_sti_setup(&mut c, seed);
            run_generated(&mut c, ee::s05::f_002127e8__generated);
            costs.insert(c.cycles);
        }
        assert!(costs.len() >= 3, "only {} paths: {costs:?}", costs.len());
    }
}
